// CÓDIGO N8N - IDENTIFICADOR DE TAGS
// ============================================
// Este código processa tags do cliente e busca
// correspondências na tabela do Supabase
// ============================================

// 1. PEGAR TODAS AS TAGS DO SUPABASE (do node "Get many rows")
const supabaseTags = $('Get many rows').all().map(item => item.json);

// 2. PEGAR OS DADOS DO CLIENTE (do node "Edit Fields")
const clientData = $('Edit Fields').first().json;

// 3. PEGAR AS ETIQUETAS (TAGS) DO CLIENTE
// O campo "Etiquetas" contém o array: ["5521968482967:28","5521968482967:12"]
const clientTagsRaw = clientData.Etiquetas;

console.log('=== DEBUG INICIAL ===');
console.log('Dados do cliente:', JSON.stringify(clientData, null, 2));
console.log('Campo Etiquetas (bruto):', clientTagsRaw);
console.log('Tipo do campo Etiquetas:', typeof clientTagsRaw);
console.log('Total de tags no Supabase:', supabaseTags.length);

// 4. FUNÇÃO PARA EXTRAIR LABEL_LID DAS TAGS DO CLIENTE
function extractLabelLids(tagsInput) {
  console.log('--- Iniciando extração de label_lids ---');
  console.log('Input recebido:', tagsInput);
  console.log('Tipo:', typeof tagsInput);

  // Se não houver tags, retorna array vazio
  if (!tagsInput || tagsInput === null || tagsInput === undefined) {
    console.log('⚠️ Nenhuma tag encontrada (null/undefined)');
    return [];
  }

  // Se vier como array direto: ["5521968482967:28","5521968482967:12"]
  if (Array.isArray(tagsInput)) {
    console.log('✓ Tags vieram como array direto');
    const labelLids = tagsInput.map(tag => {
      const tagStr = String(tag);
      console.log(`  Processando tag: "${tagStr}"`);

      // Extrai APENAS o número após os ":" (ignora o número do WhatsApp)
      // Exemplo: "5521968482967:28" → "28"
      if (tagStr.includes(':')) {
        const parts = tagStr.split(':');
        const labelLid = parts[parts.length - 1].trim();
        console.log(`  → Label LID extraído: "${labelLid}"`);
        return labelLid;
      }

      console.log(`  → Tag sem ":", usando valor completo: "${tagStr}"`);
      return tagStr.trim();
    });

    console.log('✓ Label LIDs finais extraídos:', labelLids);
    return labelLids;
  }

  // Se vier como string (ex: '["5521968482967:28","5521968482967:12"]')
  if (typeof tagsInput === 'string') {
    console.log('✓ Tags vieram como string, tentando converter...');

    try {
      // Tenta fazer parse direto
      const parsed = JSON.parse(tagsInput);
      if (Array.isArray(parsed)) {
        console.log('✓ Parse bem-sucedido, processando array...');
        return extractLabelLids(parsed); // Chama recursivamente
      }
    } catch (e) {
      console.log('✗ Erro no parse JSON:', e.message);

      // Tenta método alternativo: buscar padrões ":NUMBER"
      const matches = tagsInput.match(/:(\d+)/g);
      if (matches) {
        const labelLids = matches.map(m => m.substring(1)); // Remove o ":"
        console.log('✓ Label LIDs extraídos via regex:', labelLids);
        return labelLids;
      }
    }
  }

  // Se vier como número único
  if (typeof tagsInput === 'number') {
    console.log('✓ Tag veio como número único:', tagsInput);
    return [String(tagsInput)];
  }

  console.log('✗ Formato não reconhecido, retornando array vazio');
  return [];
}

// 5. EXTRAIR OS LABEL_LIDs DO CLIENTE
const clientLabelLids = extractLabelLids(clientTagsRaw);

