  // Busca a tag no array do Supabase que tenha o label_lid correspondente
  const matchedTag = supabaseTags.find(tag => {
    // Converte ambos para string e remove espaços
    const tagLabelLid = String(tag.label_lid).trim();
    const searchLabelLid = String(labelLid).trim();

    // Debug da comparação
    const match = tagLabelLid === searchLabelLid;
    if (match) {
      console.log(`  ✓ MATCH! "${tagLabelLid}" === "${searchLabelLid}"`);
    }

    return match;
  });

  if (matchedTag) {
    console.log(`  ✓ Tag encontrada: "${matchedTag.name}" (ID: ${matchedTag.id})`);

    matchedTags.push({
      // Dados da tag
      label_lid: labelLid,
      tag_id: matchedTag.id,
      tag_name: matchedTag.name,
      tag_color: matchedTag.color,
      organization_id: matchedTag.organization_id,
      created_at: matchedTag.created_at,

      // Dados do cliente (mantém tudo para uso posterior)
      client_phone: clientData['Número de celular'],
      client_name: clientData.Nome,
      client_bot_name: clientData['Bot name'],
      client_message: clientData.Mensagem,
      client_track_source: clientData['Track Source'],
      client_message_type: clientData['Tipo de Mensagem'],
      client_conversation_id: clientData['Id da Etiqueta'],
      client_message_id: clientData['ID Da Mensagem'],
      client_all_data: clientData
    });
  } else {
    console.error(`  ✗ Tag com label_lid "${labelLid}" NÃO encontrada no Supabase`);
    console.log('  Verificando se existe alguma tag similar...');

    // Tenta busca aproximada
    const similar = supabaseTags.find(tag => 
      String(tag.label_lid).includes(labelLid) || 
      labelLid.includes(String(tag.label_lid))
    );

    if (similar) {
      console.log(`  → Tag similar encontrada: label_lid="${similar.label_lid}", name="${similar.name}"`);
    } else {
      console.log('  → Nenhuma tag similar encontrada');
    }
  }
});

console.log('=== RESULTADO ===');
console.log(`Total de tags identificadas: ${matchedTags.length}`);

// 7. VERIFICAÇÃO: Se não encontrou nenhuma tag
if (matchedTags.length === 0) {
  console.error('❌ ERRO: Nenhuma tag correspondente foi encontrada!');
  console.log('Possíveis causas:');
  console.log('1. Os label_lid do cliente não existem na tabela do Supabase');
  console.log('2. Formato incorreto das tags');
  console.log('3. Campo "label_lid" com nome diferente no Supabase');

  // Retorna aviso para o próximo node
  return [{
    json: {
      error: true,
      message: 'Nenhuma tag correspondente encontrada',
      client_tags: clientTagsRaw,
      client_label_lids: clientLabelLids,
      client_data: clientData
    }
  }];
}

