    const labelLids = tagsInput.map(tag => {
      const tagStr = String(tag);
      console.log(`  Processando tag: "${tagStr}"`);

      // Extrai APENAS o número após os ":" (ignora o número do WhatsApp)
      // Exemplo: "5521968482967:28" → "28"
      if (tagStr.includes(':')) {
        const parts = tagStr.split(':');
        const labelLid = parts[parts.length - 1].trim();
        console.log(`  → Label LID extraído: "${labelLid}"`);
        return labelLid;
      }

      console.log(`  → Tag sem ":", usando valor completo: "${tagStr}"`);
      return tagStr.trim();
    });

    console.log('✓ Label LIDs finais extraídos:', labelLids);
    return labelLids;
  }

  // Se vier como string (ex: '["5521968482967:28","5521968482967:12"]')
  if (typeof tagsInput === 'string') {
    console.log('✓ Tags vieram como string, tentando converter...');

    try {
      // Tenta fazer parse direto
      const parsed = JSON.parse(tagsInput);
      if (Array.isArray(parsed)) {
        console.log('✓ Parse bem-sucedido, processando array...');
        return extractLabelLids(parsed); // Chama recursivamente
      }
    } catch (e) {
      console.log('✗ Erro no parse JSON:', e.message);

      // Tenta método alternativo: buscar padrões ":NUMBER"
      const matches = tagsInput.match(/:(\d+)/g);
      if (matches) {
        const labelLids = matches.map(m => m.substring(1)); // Remove o ":"
        console.log('✓ Label LIDs extraídos via regex:', labelLids);
        return labelLids;
      }
    }
  }

  // Se vier como número único
  if (typeof tagsInput === 'number') {
    console.log('✓ Tag veio como número único:', tagsInput);
    return [String(tagsInput)];
  }

  console.log('✗ Formato não reconhecido, retornando array vazio');
  return [];
}

