// ─────────────────────────────────────────────
// SPLITTER DE MENSAGENS WHATSAPP — sem IA
// Substitui o Parser Chain + OutputParser
// Input esperado: {{ $('AI Agent').first().json.output }}
// ─────────────────────────────────────────────

const MAX_CHARS = 500;

// 1. Pega o output do AI Agent
const rawText = $('AI Agent').first().json.output ?? '';

// 2. Normaliza formatação Markdown → WhatsApp
function normalizeFormatting(text) {
  // ** negrito ** → * negrito *
  text = text.replace(/\*\*(.+?)\*\*/g, '*$1*');
  // Substitui "Prazer" por "Feliz em conhecer"
  text = text.replace(/\bPrazer\b/g, 'Feliz em conhecer');
  return text;
}

// 3. Detecta se um bloco é uma lista de bullet points (- item)
function isBulletList(block) {
  const lines = block.trim().split('\n');
  return lines.length > 1 && lines.every(l => l.trim().startsWith('-') || l.trim() === '');
}

// 4. Remove ponto final do término da mensagem (humaniza)
function removeTrailingPeriod(text) {
  return text.replace(/\.\s*$/, '');
}

// 5. Divide o texto em blocos respeitando as regras
function splitMessage(text) {
  const results = [];

  // Divide por quebra de linha dupla (parágrafos)
  const paragraphs = text.split(/\n{2,}/);

  for (const paragraph of paragraphs) {
    const trimmed = paragraph.trim();
    if (!trimmed) continue;

    // Listas: mantém como bloco único indivisível
    if (isBulletList(trimmed)) {
      results.push(trimmed);
      continue;
    }

    // Divide por sentenças: ., !, ?
    // Mantém o delimitador junto com o trecho
    const sentences = trimmed.split(/(?<=[.!?])\s+/);
    let buffer = '';

    for (const sentence of sentences) {
      const candidate = buffer ? buffer + ' ' + sentence : sentence;

      if (candidate.length <= MAX_CHARS) {
        buffer = candidate;
      } else {
        // Salva o buffer atual se existir
        if (buffer.trim()) {
          results.push(buffer.trim());
        }
        // Inicia novo buffer com a sentença atual
        // Se a sentença sozinha ultrapassar MAX_CHARS, divide por \n
        if (sentence.length > MAX_CHARS) {
          const lines = sentence.split('\n');
          let lineBuf = '';
          for (const line of lines) {
            const lc = lineBuf ? lineBuf + '\n' + line : line;
            if (lc.length <= MAX_CHARS) {
              lineBuf = lc;
            } else {
              if (lineBuf.trim()) results.push(lineBuf.trim());
              lineBuf = line;
            }
          }
          buffer = lineBuf;
        } else {
          buffer = sentence;
        }
      }
    }

    if (buffer.trim()) {
      results.push(buffer.trim());
    }
  }

  return results
    .map(msg => removeTrailingPeriod(msg))
    .filter(msg => msg.trim().length > 0);
}

// 6. Executa
const normalized = normalizeFormatting(rawText);
const messages = splitMessage(normalized);

// 7. Retorna um item por mensagem (equivale ao Split Out)
return messages.map(msg => ({ json: { message: msg } }));
